-- Rolled-back test of migration 20261118150000_fk_indexes.sql (SHOULD batch A item 17, 18 Nov 2026): after it, no public foreign key lacks a covering index, and the migration made indexes only.
-- Before the apply, run both in ONE rolled-back statement, migration first:
--   node scripts/run-rolled-back-test.mjs <out.sql> supabase/tests/fk_indexes.sql supabase/migrations/20261118150000_fk_indexes.sql
-- After the apply, run this file alone (it then only checks the end state). The block ends with `raise exception` so nothing is kept.
do $$
declare
  r text := '';
  n_unindexed int;
  n_new int;
  n_bad int;
begin
  select count(*) into n_unindexed from (
    select c.oid from pg_constraint c join pg_class cl on cl.oid = c.conrelid join pg_namespace ns on ns.oid = cl.relnamespace
    where c.contype = 'f' and ns.nspname = 'public' and not exists (
      select 1 from pg_index i where i.indrelid = c.conrelid and i.indisvalid
        and (string_to_array(i.indkey::text, ' ')::int2[])[1:array_length(c.conkey, 1)] @> c.conkey::int2[]
        and (string_to_array(i.indkey::text, ' ')::int2[])[1:array_length(c.conkey, 1)] <@ c.conkey::int2[]
        and array_length(string_to_array(i.indkey::text, ' '), 1) >= array_length(c.conkey, 1))
  ) q;
  r := r || 'F1 foreign keys in public with no covering index: ' || n_unindexed || case when n_unindexed = 0 then ' ok' else ' FAIL (want 0)' end || E'\n';
  -- the 72 indexes this migration makes (names as in the migration file)
  select count(*) into n_new from pg_indexes where schemaname = 'public' and indexname = any(array['idx_admin_audit_logs_admin_id','idx_conversations_session_id','idx_conversations_tutor_id','idx_countries_default_currency_code','idx_credential_definitions_entry_sub_tier_id','idx_curricula_country_code','idx_guardian_consents_learner_profile_id','idx_guardian_learner_intents_guardian_id','idx_institution_curricula_curriculum_id','idx_learner_tutor_choices_chosen_by','idx_learner_tutor_choices_tutor_id','idx_messages_sender_id','idx_notifications_related_session_id','idx_parent_student_links_student_id','idx_payout_batches_processed_by_admin_id','idx_payout_sessions_session_id','idx_payouts_currency_code','idx_payouts_payout_account_id','idx_platform_disputes_assigned_admin_id','idx_platform_disputes_currency_code','idx_platform_disputes_raised_by_id','idx_platform_suggestions_handled_by','idx_policy_acceptances_accepted_by_profile_id','idx_promo_codes_referring_tutor_id','idx_reviews_student_id','idx_school_results_checked_by','idx_school_results_entered_by','idx_school_results_consents_consented_by','idx_schools_institutions_country_code','idx_schools_institutions_curriculum_id','idx_session_requests_curriculum_id','idx_session_requests_enrollment_id','idx_session_requests_first_offer_tutor_id','idx_session_requests_institution_id','idx_session_requests_min_sub_tier_id','idx_session_requests_payment_card_id','idx_session_requests_requested_by_profile_id','idx_session_requests_resulting_session_id','idx_session_requests_tier_id','idx_sessions_currency_code','idx_student_academic_records_tutor_id','idx_student_profiles_school_id','idx_student_subject_enrollments_school_id','idx_sub_tier_definitions_tier_id','idx_subject_candidates_requested_by','idx_system_settings_last_updated_by','idx_tier1_academic_records_checked_by','idx_tier1_academic_records_subject_name','idx_tier1_attempts_subject_name','idx_tier1_items_subject_name','idx_tier1_training_module','idx_tier1_training_recorded_by','idx_tier_definitions_currency_code','idx_tutor_certifications_tutor_id','idx_tutor_credentials_assigned_sub_tier_id','idx_tutor_credentials_credential_code','idx_tutor_credentials_document_id','idx_tutor_credentials_verified_by','idx_tutor_ended_pairings_learner_id','idx_tutor_languages_language_code','idx_tutor_profiles_credential_floor_sub_tier_id','idx_tutor_profiles_currency_code','idx_tutor_profiles_current_sub_tier_id','idx_tutor_profiles_current_tier_id','idx_tutor_profiles_institution_id','idx_tutor_progression_logs_tutor_id','idx_tutor_verification_audits_document_id','idx_tutor_verification_audits_reviewer_id','idx_tutor_verification_documents_tutor_id','idx_tutor_waitlist_institution_id','idx_tutor_waitlist_student_id','idx_video_rooms_host_id']);
  r := r || 'F2 of the 72 named indexes, present: ' || n_new || case when n_new = 72 then ' ok' else ' FAIL (want 72)' end || E'
';
  -- each is a plain single-column b-tree
  select count(*) into n_bad from pg_indexes x
   where x.schemaname = 'public' and x.indexname = any(array['idx_admin_audit_logs_admin_id','idx_conversations_session_id','idx_conversations_tutor_id','idx_countries_default_currency_code','idx_credential_definitions_entry_sub_tier_id','idx_curricula_country_code','idx_guardian_consents_learner_profile_id','idx_guardian_learner_intents_guardian_id','idx_institution_curricula_curriculum_id','idx_learner_tutor_choices_chosen_by','idx_learner_tutor_choices_tutor_id','idx_messages_sender_id','idx_notifications_related_session_id','idx_parent_student_links_student_id','idx_payout_batches_processed_by_admin_id','idx_payout_sessions_session_id','idx_payouts_currency_code','idx_payouts_payout_account_id','idx_platform_disputes_assigned_admin_id','idx_platform_disputes_currency_code','idx_platform_disputes_raised_by_id','idx_platform_suggestions_handled_by','idx_policy_acceptances_accepted_by_profile_id','idx_promo_codes_referring_tutor_id','idx_reviews_student_id','idx_school_results_checked_by','idx_school_results_entered_by','idx_school_results_consents_consented_by','idx_schools_institutions_country_code','idx_schools_institutions_curriculum_id','idx_session_requests_curriculum_id','idx_session_requests_enrollment_id','idx_session_requests_first_offer_tutor_id','idx_session_requests_institution_id','idx_session_requests_min_sub_tier_id','idx_session_requests_payment_card_id','idx_session_requests_requested_by_profile_id','idx_session_requests_resulting_session_id','idx_session_requests_tier_id','idx_sessions_currency_code','idx_student_academic_records_tutor_id','idx_student_profiles_school_id','idx_student_subject_enrollments_school_id','idx_sub_tier_definitions_tier_id','idx_subject_candidates_requested_by','idx_system_settings_last_updated_by','idx_tier1_academic_records_checked_by','idx_tier1_academic_records_subject_name','idx_tier1_attempts_subject_name','idx_tier1_items_subject_name','idx_tier1_training_module','idx_tier1_training_recorded_by','idx_tier_definitions_currency_code','idx_tutor_certifications_tutor_id','idx_tutor_credentials_assigned_sub_tier_id','idx_tutor_credentials_credential_code','idx_tutor_credentials_document_id','idx_tutor_credentials_verified_by','idx_tutor_ended_pairings_learner_id','idx_tutor_languages_language_code','idx_tutor_profiles_credential_floor_sub_tier_id','idx_tutor_profiles_currency_code','idx_tutor_profiles_current_sub_tier_id','idx_tutor_profiles_current_tier_id','idx_tutor_profiles_institution_id','idx_tutor_progression_logs_tutor_id','idx_tutor_verification_audits_document_id','idx_tutor_verification_audits_reviewer_id','idx_tutor_verification_documents_tutor_id','idx_tutor_waitlist_institution_id','idx_tutor_waitlist_student_id','idx_video_rooms_host_id']) and x.indexdef !~ '^CREATE INDEX idx_[a-z0-9_]+ ON public\.[a-z0-9_]+ USING btree \([a-z0-9_]+\)$';
  r := r || 'F3 of them, not a plain one-column b-tree: ' || n_bad || case when n_bad = 0 then ' ok' else ' FAIL (want 0)' end || E'
';
  raise exception E'% lines, % FAIL\n%', 3, (select count(*) from unnest(string_to_array(r, E'\n')) l where l like '%FAIL%'), r;
end $$;
